/**
 * Minimal i18n: German is the default language, English the second. Three catalogs are merged:
 *  - ui.*.ts        UI text written in the frontend
 *  - messages.*.ts  text for the message keys the Go engine emits (log, prompts, notes, errors)
 *  - data.gen.ts    text from internal/data/*.json (German) and internal/data/i18n/en.json (English),
 *                   generated by `just gen-i18n`
 * Catalog values use {param} placeholders. A key with a numeric `count` param uses `<key>_one` /
 * `<key>_other` when present (Intl.PluralRules).
 */
import { useSyncExternalStore } from "react";
import { readStorage, writeStorage } from "@/lib/storage";
import { dataDe, dataEn } from "./data.gen";
import { messagesDe } from "./messages.de";
import { messagesEn } from "./messages.en";
import { uiDe } from "./ui.de";
import { uiEn } from "./ui.en";
import type { Lang, Msg, MsgArg } from "./types";

export type { Lang, Msg, MsgArg } from "./types";
export { LANGS } from "./types";

/** Keys of the frontend UI catalog (checked at compile time). */
export type UiKey = keyof typeof uiDe;
export type Args = Record<string, MsgArg | null | undefined>;

const catalogs: Record<Lang, Record<string, string>> = {
  de: { ...dataDe, ...messagesDe, ...uiDe },
  en: { ...dataEn, ...messagesEn, ...uiEn },
};

const LANG_KEY = "ruderspiel.lang";

function detectLang(): Lang {
  const stored = readStorage(LANG_KEY);
  if (stored === "de" || stored === "en") return stored;
  const prefs = typeof navigator === "undefined" ? [] : (navigator.languages ?? [navigator.language]);
  for (const p of prefs) {
    const l = p?.toLowerCase() ?? "";
    if (l.startsWith("de")) return "de";
    if (l.startsWith("en")) return "en";
  }
  return prefs.length ? "en" : "de";
}

let lang: Lang = detectLang();
const listeners = new Set<() => void>();
applyDocumentLang();

function applyDocumentLang() {
  if (typeof document === "undefined") return;
  document.documentElement.lang = lang;
  document.title = lookup("app.title") ?? document.title;
}

export function getLang(): Lang {
  return lang;
}

export function setLang(next: Lang): void {
  if (next === lang) return;
  lang = next;
  writeStorage(LANG_KEY, next);
  applyDocumentLang();
  listeners.forEach((l) => l());
}

function subscribe(l: () => void) {
  listeners.add(l);
  return () => listeners.delete(l);
}

/** Current language; re-renders the caller on a switch. Used at the app root so the whole tree updates. */
export function useLang(): Lang {
  return useSyncExternalStore(subscribe, getLang, getLang);
}

function lookup(key: string): string | undefined {
  return catalogs[lang][key] ?? catalogs.de[key];
}

function pluralKey(key: string, args: Args | undefined): string {
  const count = args?.count;
  if (typeof count !== "number") return key;
  const form = `${key}_${new Intl.PluralRules(lang).select(count)}`;
  if (lookup(form) !== undefined) return form;
  const other = `${key}_other`;
  return lookup(other) !== undefined ? other : key;
}

/** Formats a number for the current language (1.5 → "1,5" in German). */
export function fmtNum(n: number, opts?: Intl.NumberFormatOptions): string {
  return new Intl.NumberFormat(lang, opts).format(n);
}

/** Joins items as a natural-language list ("A, B und C" / "A, B, and C"). */
export function fmtList(items: string[]): string {
  return new Intl.ListFormat(lang, { style: "long", type: "conjunction" }).format(items);
}

function isMsg(a: unknown): a is Msg {
  return typeof a === "object" && a !== null && !Array.isArray(a) && typeof (a as Msg).key === "string";
}

function argText(a: MsgArg | null | undefined, name = ""): string {
  if (a === null || a === undefined) return "";
  if (typeof a === "number") return fmtNum(a);
  if (typeof a === "string") return a;
  if (Array.isArray(a)) {
    const items = a.map((x) => argText(x));
    // "entries" (results, moods) are enumerations, not sentences: commas only.
    if (name === "entries") return items.join(", ");
    // "details"/"cards" are sentences of their own: join with spaces.
    if (name === "details" || name === "cards") return items.join(" ");
    return fmtList(items);
  }
  if (isMsg(a)) return tm(a);
  return String(a);
}

function interpolate(template: string, args: Args | undefined): string {
  if (!args) return template;
  return template.replace(/\{(\w+)\}/g, (m, name: string) => (name in args ? argText(args[name], name) : m));
}

/** Translates any catalog key (UI, engine message or data). Missing keys render as the key itself. */
export function tk(key: string, args?: Args): string {
  const k = pluralKey(key, args);
  const template = lookup(k);
  if (template === undefined) {
    if (import.meta.env.DEV) console.warn(`[i18n] missing key ${key}`);
    return key;
  }
  return interpolate(template, args);
}

/** Translates a UI key. */
export function t(key: UiKey, args?: Args): string {
  return tk(key, args);
}

/** Renders an engine message. */
export function tm(m: Msg | null | undefined): string {
  if (!m) return "";
  return tk(m.key, m.args as Args | undefined).trim();
}

/** True when the catalog has the key (in any language). */
export function hasKey(key: string): boolean {
  return lookup(key) !== undefined;
}

/** Data text by key with a fallback (e.g. the German name the engine still sends). */
export function tData(key: string, fallback = ""): string {
  const v = lookup(key);
  return v === undefined ? fallback : v;
}
